// Types for core.js, the WebAssembly build of core/ (generated by `node scripts/core.mjs wasm`).
// See core/bindings/wasm.cpp for what each function does on the C++ side.
import type { Category, Kind, Vec3 } from '../participants';
import type { Waypoint } from '../motion';
import type { IncidentEvent, Storyboard } from '../storyboard';

/** A film as flat arrays; see generate_film_js in core/bindings/wasm.cpp for the layout. */
export interface RawFilm {
  fps: number;
  duration: number;
  actors: number;
  times: Float64Array;
  rain: Uint8Array;
  positions: Float64Array;
  visible: Uint8Array;
}

export interface CoreModule {
  catalogue(): Record<Category, Kind[]>;
  categoryOf(kind: string): Category;
  canMove(category: Category): boolean;
  emptyStoryboard(): Storyboard;
  place(sb: Storyboard, kind: string, position: Vec3): Storyboard;
  reposition(sb: Storyboard, participantId: string, position: Vec3): Storyboard;
  addWaypoint(sb: Storyboard, participantId: string, waypoint: Waypoint): Storyboard;
  addEvent(sb: Storyboard, event: IncidentEvent): Storyboard;
  positionAt(start: Vec3, waypoints: readonly Waypoint[], t: number): Vec3;
  generateFilm(sb: Storyboard, fps: number): RawFilm;
}

export default function createCore(): Promise<CoreModule>;
